"""Proration helpers for mid-cycle plan changes."""


def prorate(amount_cents, days_used, days_in_cycle):
    if days_in_cycle <= 0:
        return 0
    return max(0, round(amount_cents * days_used / days_in_cycle))


def refund_due(paid_cents, days_used, days_in_cycle):
    return paid_cents - prorate(paid_cents, days_used, days_in_cycle)
